# shop/tillpoint_client.py
import json, urllib.request

class TillpointClient:
    def __init__(self, base_url, api_key, timeout=8):
        self.base_url = base_url.rstrip('/')
        self.api_key = api_key
        self.timeout = timeout

    def _headers(self, extra=None):
        h = {"Authorization": f"Bearer {self.api_key}", "Content-Type": "application/json"}
        if extra:
            h.update(extra)
        return h

    def create_charge(self, cart_id, amount_minor, currency, card_token):
        body = json.dumps({"amount": amount_minor, "currency": currency,
                           "source": card_token, "reference": cart_id}).encode()
        req = urllib.request.Request(f"{self.base_url}/v1/charges", data=body,
                                     headers=self._headers(), method="POST")
        with urllib.request.urlopen(req, timeout=self.timeout) as r:
            return json.loads(r.read())

